create extension if not exists "uuid-ossp";
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, email text unique, phone text, city text, user_type text not null default 'user' check (user_type in ('user','owner','investor','admin')), bio text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.categories (id uuid primary key default uuid_generate_v4(), name_ar text not null, name_en text, slug text unique not null, description text, is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.projects (id uuid primary key default uuid_generate_v4(), owner_id uuid not null references public.profiles(id) on delete cascade, category_id uuid references public.categories(id) on delete set null, title text not null, slug text unique not null, short_description text, description text, city text, opportunity_type text, project_stage text, asking_price numeric, annual_revenue numeric, annual_profit numeric, reason_for_listing text, status text not null default 'pending' check (status in ('draft','pending','approved','rejected','closed')), is_featured boolean not null default false, views_count integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.project_images (id uuid primary key default uuid_generate_v4(), project_id uuid not null references public.projects(id) on delete cascade, image_url text not null, storage_path text, sort_order integer not null default 0, created_at timestamptz not null default now());
create table if not exists public.project_files (id uuid primary key default uuid_generate_v4(), project_id uuid not null references public.projects(id) on delete cascade, file_url text not null, storage_path text, file_name text, file_type text, created_at timestamptz not null default now());
create table if not exists public.interests (id uuid primary key default uuid_generate_v4(), project_id uuid not null references public.projects(id) on delete cascade, sender_id uuid not null references public.profiles(id) on delete cascade, owner_id uuid not null references public.profiles(id) on delete cascade, message text, status text not null default 'pending' check (status in ('pending','accepted','rejected','closed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(project_id, sender_id));
create table if not exists public.reports (id uuid primary key default uuid_generate_v4(), reporter_id uuid references public.profiles(id) on delete set null, project_id uuid references public.projects(id) on delete cascade, reason text not null, details text, status text not null default 'pending' check (status in ('pending','reviewed','dismissed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.notifications (id uuid primary key default uuid_generate_v4(), user_id uuid not null references public.profiles(id) on delete cascade, title text not null, body text, type text not null default 'general', link_url text, is_read boolean not null default false, created_at timestamptz not null default now(), read_at timestamptz);
create table if not exists public.contact_messages (id uuid primary key default uuid_generate_v4(), user_id uuid references public.profiles(id) on delete set null, full_name text not null, email text not null, phone text, subject text not null, message text not null, status text not null default 'new' check (status in ('new','in_progress','resolved','closed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql security definer set search_path = public as $$ select exists (select 1 from public.profiles where id = auth.uid() and user_type = 'admin'); $$;
alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.projects enable row level security; alter table public.interests enable row level security; alter table public.reports enable row level security; alter table public.notifications enable row level security; alter table public.contact_messages enable row level security;
insert into public.categories (name_ar,name_en,slug,description,is_active) values ('تقنية','Technology','technology','مشاريع تقنية وبرمجية',true),('مطاعم ومقاهي','Restaurants & Cafes','restaurants-cafes','مطاعم ومقاهي وخدمات ضيافة',true),('تجارة إلكترونية','E-commerce','ecommerce','متاجر إلكترونية',true),('صناعة','Manufacturing','manufacturing','مشاريع صناعية',true) on conflict (slug) do nothing;
